"OLAYLAR_EK5:1918-04-14:0":{"b": ["د باتوم بېرته نیول", "d37a1a0d"], "d": ["کله چې د برست-لیتوفسک تړون سره روسیه له جګړې ووته، ختیځ ته وړاندې تلونکي عثماني لښکر د 1878 کال له لاسه تللی د باتوم بندر څلوېښت کاله وروسته بېرته ونیو. دا بندر چې د تورې سمندرګي ختیځ سر کې و، د باکو تیلو سمندري وتلار و. لاسته راوړنه یوازې اوه میاشتې دوام وکړ؛ د مدروس متارکې وروسته سیمه تخلیه کېدونکې وه.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["الویهٔ ثلاثه: قارص د عثماني ادارې ته ننوت", "02cbf0b3"], "d": ["په برست-لیتوفسک کې پرېکړه شوې وه چې د 1878 د برلین تړون سره له لاسه تللي درې سنجاقونه — قارص، اردهان او باتوم — بېرته ورکړل شي؛ عثماني لښکر د 1918 د اپرېل په 3 مه اردهان، د اپرېل په 14 مه باتوم او د اپرېل په 25 مه قارص ته ننوت او اداره عملاً ټینګه شوه. دا ځمکې چې «الویهٔ ثلاثه» بلل کېدې، د 93 جګړې راهیسې د روان تاوان جبران وګڼل شو. د متارکې وروسته به بیا له لاسه ووځي او قطعي به یوازې د 1921 د قارص تړون سره ترکیې پورې وتړل شي.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["ایغدیر ونیول شو — د اراس په درې کې پرمختګ", "87ebf4d3"], "d": ["د 1918 په فبرورۍ کې پیل شوي وړاندې عملیاتو په چوکاټ کې ترکي ټولیو د اراس شمال ته په سردارآباد کې ارمني ټولیو ته ماتې ورکړه او د 1918 د مې په 20 مه یې ایغدیر ونیو. ایغدیر د الویهٔ ثلاثه برخه نه وه، بلکې د ایروان ګوبرنیا د سورملي قضا وه؛ شاوخوا 180 کاله وروسته په سیمه کې لومړنۍ عثماني اداره جوړه شوه.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["د پنځم محمد رشاد وفات او د شپږم محمد وحیدالدین پر تخت کېناستل", "d302ba07"], "d": ["پنځم محمد رشاد چې نهه کلنه واکمني یې د طرابلس غرب، بالکان او نړیوالو جګړو سره تېره شوه، د جګړې په تر ټولو حساسه دوره کې وفات شو او پر ځای یې ورور وحیدالدین د شپږم محمد په نوم تخت ته وخوت. نوي سلطان هڅه وکړه چې د اتحادي کادر له سرپرستۍ خلاص شي؛ څلور میاشتې وروسته چې متارکه لاسلیک شوه، اړ شو چې د امپراتورۍ د له منځه تلو اداره وکړي. دا د عثماني کورنۍ شپږ دېرشم او وروستی سلطان و.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["استانبول ته د ائتلافي بحري ځواک راتګ او د ښار عملي اشغال", "d10cb14d"], "d": ["د مدروس متارکې وروسته له انګلیسي، فرانسوي، ایټالیايي او یوناني بېړیو جوړ له شپېتو زیات متحد بحري ځواک د دولما باغچې مخې ته لنګر واچاوه او استانبول عملاً تر اشغال لاندې راغی. څلور سوه پنځه شپېته کاله وروسته پلازمېنه د لومړي ځل لپاره د بهرنیو سرتېرو کنټرول ته ولاړه. د مصطفی کمال پاشا هغه خبره چې روایت دی په همدې ورځ حیدرپاشا ته په ښکته کېدو او منظرې ته په کتلو کې یې کړې وه، «څنګه چې راغلي، هماغسې به ولاړ شي»، به د ملي مبارزې له سمبولیکو جملو څخه شي.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["د اراس په سیمه کې شاتګ: ایغدیر تخلیه شو", "57572ab4"], "d": ["د مدروس متارکې د هغه حکم له مخې چې د 1914 پولې شاته تګ غوښته، یعقوب شوکي پاشا د نومبر د 21 مې امرنامې سره امر وکړ چې د برست-لیتوفسک له پولې بهر ټولۍ دې تر د ډسمبر د 4 مې بېرته راوغوښتل شي؛ ایغدیر او شاوخوا یې په دې نېټه بشپړه تخلیه شوه. وروسته د اراس-ترکي حکومت د 1918 د ډسمبر په پای کې د ارمنیانو له خوا ړنګ شو.", "68b8ff9a"]},
