"OLAYLAR_EK8:1637-06-18:0":{"b": ["د ازاق کلا د دُن قزاقانو لاس ته لوېدل", "ba068b2f"], "d": ["د دُن قزاقانو د 1637 د اپریل په 21 محاصره کړې د ازاق کلا دوه میاشتې وروسته ونیوله؛ هغه کلا چې د تورې بحیرې شمال ختیځه دروازه او د دُن د سوداګرۍ کیلي وه، د لومړي ځل لپاره له عثماني لاسه ووته. د TDV اسلامي دايرة المعارف د ازاق د مادې له مخې، قزاقانو کلا په 1637 کې ونیوله، په 1641 کې د دېلي حسین پاشا تر قوماندې لاندې د دریو میاشتو لویې محاصرې پر وړاندې ودرېدل او یوازې په 1642 کې د کریمیا خان محمد ګرای په راتګ کلا يې تخلیه کړه. دولت په هغه وخت کې د بغداد په جبهه بوخت و؛ د پنځو کلونو لپاره د کلا نه ساتل کېدل د تورې بحیرې د «عثماني جهیل» صفت لومړی درز دی.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["د لیمنوس او ساموتراکي بېرته نیول", "c445553b"], "d": ["د 1657 د اګست په 31 د بوزجه‌اطه له آزادولو وروسته کوپرولو محمد پاشا بحري ځواک شمال ته واړاوه او هغه لیمنوس او ساموتراکي يې بېرته ونیول چې وینیز شپاړس میاشتې په لاس کې ساتلي وو. د TDV اسلامي دايرة المعارف د لیمنوس د مادې له مخې، ټاپو د 1656 په جولای کې د وینیز لاس ته لوېدلی و او د 1657 په نومبر کې بېرته ونیول شو. په دې توګه د چناق کلا تنګي په خوله کې د وینیز محاصره بشپړه ماته شوه او استانبول ته د غلې لاره بیا خوندي شوه؛ دا د فوق العاده واکونو سره راغلي صدراعظم د لومړي کال تر ټولو محسوسه لاسته راوړنه ده.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["کنین وینیز ته له لاسه وتل — د 166 کلنې دلماسیا سرحدي کلا سقوط", "252406b7"], "d": ["د 1683 د ویانا له ماتې وروسته په پیل شوې څو جبهه‌ییزه جګړه کې وینیزي ځواکونه د دلماسیا دننه برخو ته مخکې لاړل. کنین، چې د دلماسیا جنرال جیرولامو کورنارو محاصره کړی و، د دولسو ورځو محاصرې وروسته بیګلربیګي محمد پاشا تسلیم کړ. کنین د دلماسیا د سرحدي کرښې کلیدي کلا وه، چې غازي خسرو بېګ په 1522 کې فتح کړې وه او 166 کاله په عثماني لاس کې پاتې وه؛ د هغې له لاسه وتلو سیمه تر ډېره وینیز ته پرانیسته.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["بصره له ایراني اشغاله بېرته نیول", "5b10c5c1"], "d": ["بصره، چې د کریم خان زند ورور صادق خان په 1776 کې نیولې وه، د 1779 د مارچ د 2 د کریم خان له مړینې وروسته، کله چې په ایران کې د تخت جګړه پیل شوه، تخلیه کړای شوه؛ صادق خان د سلطنت دعوې سره ایران ته راستون شو. ښار د لنډې مودې لپاره د منتفق قبیلې په لاس کې پاتې شو، بیا بېرته عثماني ادارې ته ننوت. له شیرازه راستون شوی پخوانی متسلم سلیمان اغا د بصرې والي‌ټوب وغوښت او د لوی سلیمان پاشا په نوم د بصرې، بغداد او شهرزور والي شو. د خلیج سوداګري عثماني کنټرول ته راوګرځېده؛ د اشغال په کلونو کې د سوداګرۍ یوه برخه کویت ته ښویېدلې وه او له 1778 راهیسې د دښتې پوسته هم له کویته لېږل کېده.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["د تیمور شاه مړینه، د زمان شاه جلوس (دراني دولت)", "c3effdb2"], "d": ["د تیمور شاه، چې له شلو کلونو څخه ډېر يې هېواد له دننه ټینګ کړ، په مړینې سره د کندهار، هرات او کابل والیان درې وروڼه د تخت لپاره سره ولګېدل؛ د کابل والي زمان شاه، چې پلازمېنه يې په لاس کې وه، د 1793 د مې په 20 پاچا شو. د وراثت دا بحران د کورنۍ د ټوټه ټوټه کېدو د بهیر عملي پیل دی.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — په هاوایي کې د دودیز کاپو نظام پای", "0b10e1d8"], "d": ["د کامهامها لومړي له مړینې شپږ میاشتې وروسته، نوي پاچا لیهولیهو، د خپلې مور کاهومانو په ملاتړ، د ښځو او نارینه‌وو د بېل خوړلو منع (ʻaikapu) په قصد ماته کړه. دا عمل، چې د «ʻAi Noa» (آزاد خوړل) په نوم یادېږي، د دودیز کاپو دیني-حقوقي نظام ته په رسمي ډول پای ورکړ؛ په ټاپوګانو کې زاړه معبدونه (heiau) په لنډ وخت کې ونړول شول. دا د لوېدیځو میسیونرانو له راتګ (1820) مخکې تر ټولو لویه دیني-سیاسي ماتېدنه ده.", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["د لندن پروتوکول — د یونان خپلواکي منل کېدل", "4c7b4b72"], "d": ["هغه پروتوکول، چې انګلستان، فرانسې او روسیې په لندن کې لاسلیک کړ، د ادرنې د تړون له خوا اټکل شوې خودمختارۍ څخه واوښت او یونان يې د یوه خپلواک دولت په توګه ومانه. احکام: د موریا ټاپووزمه، اتیکا او اغریبوز او د سیکلاد ټاپوګان نوي دولت ته پرېښودل شول؛ پوله د ارتا-وولوس په کرښه وټاکل شوه؛ پرېکړه وشوه چې عثماني دولت ته تاوان ورکړل شي؛ د دولت د حکومت بڼه «خپلواکه پاچاهي» وټاکل شوه. دا له امپراتورۍ بېل شوی لومړنی خپلواک دولت دی او د راتلونکو بالکاني خپلواکیو حقوقي بېلګه يې جوړه کړه. یونان، چې خپلواکي يې د لندن په پروتوکول ومنل شوه، د سیکلاد ټاپوګان (ناکسوس، تینوس، سانتوریني، پاروس، میلوس، سیروس، میکونوس او نور) پکې شامل شول.", "920bfab9"]},
